import { createHash } from 'node:crypto';
import { closeSync, fstatSync, lstatSync, openSync, readSync, realpathSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateTaxonomyCatalogImport } from '../server/services/taxonomyCatalogImport';
import type { TaxonomyImport } from '../shared/explorersTaxonomyContract';
/**
 * Fixed reviewed curated term lists (books, games, apps, products) DATA only; grants
 * no database/operator authority. Generated by generate-curated-taxonomy.mjs; term ids
 * are UUIDv5 under the taxonomy ratification namespace of
 * "explorers.earth/<category>-term/<slug>". Labels are English only and flat (no
 * parents). Only games carries source mappings (IGDB genre ids).
 */
export type CuratedCategory = 'books' | 'games' | 'apps' | 'products';
export const reviewedCuratedTaxonomyDirectory = resolve(dirname(fileURLToPath(import.meta.url)), '../fixtures/taxonomy/reviewed-curated-20261023');
const expected: Readonly<Record<CuratedCategory, { bytes: number; sha256: string; inputHash: string; terms: number }>> = {
    books: { bytes: 6571, sha256: '5f6966efa14643590961024f89972d2b624a55c8ba950977661296ab3e45d673', inputHash: '0260f3de22706cb2f5441e0ecb7afed57fdb0fb6cef0b949fd7720d6ec39936e', terms: 26 },
    games: { bytes: 8615, sha256: '36c023e3cd9d62705ab6b658e10232295c05e1837b0c481af589015db93b6c5c', inputHash: 'a714486dde39d177d763fc80e67fe2ee5dcd12e8ecea0fa9020f7acbc0279015', terms: 20 },
    apps: { bytes: 5052, sha256: '5a83905ae5909070560c176289b8f3d05c0f495c390849b33d1b11239b487d11', inputHash: '653ceb7f6651ec164b2df416dfb8486d9a0e0759399e9d2d2f015b79ddbb99e4', terms: 20 },
    products: { bytes: 5135, sha256: '2e011c3b8e15edb704f4e77f4cec91cdb6ed6a53cd5f76fe7c75b080dc4adb9a', inputHash: '016107cdd033752f215d926ee5003f0c84e5e8edda13afb652e2583d3ce1461f', terms: 20 },
};
const refuse = (): never => { throw new Error('Invalid reviewed curated taxonomy input'); };
function readFixed(path: string, length: number): Buffer {
    const info = lstatSync(path);
    if (!info.isFile() || info.isSymbolicLink() || realpathSync(path) !== path || info.size !== length) refuse();
    const fd = openSync(path, 'r');
    try {
        if (fstatSync(fd).size !== length) refuse();
        const bytes = Buffer.alloc(length);
        let offset = 0;
        while (offset < length) {
            const count = readSync(fd, bytes, offset, length - offset, null);
            if (count < 1) refuse();
            offset += count;
        }
        return bytes;
    } finally {
        closeSync(fd);
    }
}
export function loadReviewedCuratedTaxonomy(category: CuratedCategory): Readonly<{ input: TaxonomyImport; inputHash: string }> {
    try {
        if (!Object.prototype.hasOwnProperty.call(expected, category)) refuse();
        const pin = expected[category];
        const bytes = readFixed(join(reviewedCuratedTaxonomyDirectory, `${category}.json`), pin.bytes);
        if (createHash('sha256').update(bytes).digest('hex') !== pin.sha256) refuse();
        const validated = validateTaxonomyCatalogImport(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)));
        const input = validated.input;
        if (validated.inputHash !== pin.inputHash || input.category !== category || input.catalogVersion !== 1 || input.defaultLocale !== 'en'
            || input.terms.length !== pin.terms || input.terms.some(term => term.parentId !== null || !term.active || Object.keys(term.labels).join(',') !== 'en')
            || input.legacySlugMappings.length || (category !== 'games' && input.sourceMappings.length)) refuse();
        return { input, inputHash: validated.inputHash };
    } catch {
        return refuse();
    }
}
